# ---------------------------------------------------------------- stats
QUERY = """
query($login: String!) {
  user(login: $login) {
    createdAt
    followers { totalCount }
    pullRequests { totalCount }
    issues { totalCount }
    repositories(ownerAffiliations: OWNER, privacy: PUBLIC, isFork: false, first: 100) {
      totalCount
      nodes {
        stargazerCount
        languages(first: 10, orderBy: {field: SIZE, direction: DESC}) {
          edges { size node { name color } }
        }
      }
    }
    repositoriesContributedTo(contributionTypes: [COMMIT, PULL_REQUEST, ISSUE, REPOSITORY]) { totalCount }
    contributionsCollection {
      totalCommitContributions
      restrictedContributionsCount
      contributionCalendar {
        totalContributions
        weeks { contributionDays { date contributionCount } }
      }
    }
  }
}
"""


def fetch_stats():
    token = os.environ.get("GITHUB_TOKEN")
    if not token:
        return None
    req = urllib.request.Request(
        "https://api.github.com/graphql",
        data=json.dumps({"query": QUERY, "variables": {"login": USER}}).encode(),
        headers={"Authorization": f"bearer {token}", "Content-Type": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=30) as r:
        resp = json.load(r)
    if resp.get("errors"):
        print("GraphQL errors:", resp["errors"])
    u = resp["data"]["user"]
    cc = u["contributionsCollection"]
    cal = [(d["date"], d["contributionCount"])
           for w in cc["contributionCalendar"]["weeks"] for d in w["contributionDays"]]
    days = [c for _, c in cal]
    langs = {}
    for repo in u["repositories"]["nodes"]:
        for e in repo["languages"]["edges"]:
            n = e["node"]["name"]
            langs.setdefault(n, [0, e["node"]["color"] or "#8b949e"])
            langs[n][0] += e["size"]
    return {
        "calendar": cal,
        "langs": sorted(([n, v[0], v[1]] for n, v in langs.items()), key=lambda x: -x[1]),
        "created": u["createdAt"][:10],
        "repos": u["repositories"]["totalCount"],
        "stars": sum(n["stargazerCount"] for n in u["repositories"]["nodes"]),
        "followers": u["followers"]["totalCount"],
        "contributed": u["repositoriesContributedTo"]["totalCount"],
        "commits": cc["totalCommitContributions"] + cc["restrictedContributionsCount"],
        "prs": u["pullRequests"]["totalCount"],
        "issues": u["issues"]["totalCount"],
        "year": cc["contributionCalendar"]["totalContributions"],
        "active": sum(1 for d in days if d > 0),
    }


def uptime(created):
    a, b = dt.date.fromisoformat(created), dt.date.today()
    months = (b.year - a.year) * 12 + b.month - a.month - (b.day < a.day)
    am = a.month - 1 + months
    days = (b - dt.date(a.year + am // 12, am % 12 + 1, min(a.day, 28))).days
    y, m = divmod(months, 12)
    return f"{y} years, {m} months, {days} days"


# ---------------------------------------------------------------- shared bits
def window(width, height, title, extra_style=""):
    return [
        f'<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" '
        f'width="{width}" height="{height}" viewBox="0 0 {width} {height}" font-family="{FONT}" font-size="14">',
        "<defs>",
        '<pattern id="scan" width="4" height="4" patternUnits="userSpaceOnUse">'
        '<rect width="4" height="1" fill="#ffffff" opacity="0.025"/></pattern>',
        '<linearGradient id="edge" x1="0" y1="0" x2="1" y2="1">'
        '<stop offset="0" stop-color="#39c5cf"/><stop offset="0.5" stop-color="#1f6feb"/>'
        '<stop offset="1" stop-color="#a371f7"/></linearGradient>',
        "</defs>",
        "<style>",
        "@keyframes fade{to{opacity:1}}",
        "@keyframes slide{from{opacity:0;transform:translateX(-8px)}to{opacity:1;transform:none}}",
        "@keyframes blink{50%{opacity:0}}",
        "@keyframes sweep{from{transform:translateY(-60px)}to{transform:translateY(" + str(height + 60) + "px)}}",
        "@keyframes border{0%,100%{stroke-opacity:.55}50%{stroke-opacity:1}}",
        ".cur{animation:blink 1s step-end infinite}",
        ".sweep{animation:sweep 5s linear infinite}",
        ".frame{animation:border 4s ease-in-out infinite}",
        extra_style,
        "</style>",
        f'<rect x="1" y="1" width="{width-2}" height="{height-2}" rx="14" fill="{BG}"/>',
        f'<path d="M1 15a14 14 0 0 1 14-14h{width-30}a14 14 0 0 1 14 14v21H1z" fill="{BAR}"/>',
        '<circle cx="24" cy="19" r="6" fill="#ff5f56"/><circle cx="44" cy="19" r="6" fill="#ffbd2e"/>'
        '<circle cx="64" cy="19" r="6" fill="#27c93f"/>',
        f'<text x="{width/2}" y="24" text-anchor="middle" fill="#6e7681" font-size="13">{escape(title)}</text>',
    ]


def close(width, height):
    return [
        f'<rect x="1" y="36" width="{width-2}" height="{height-37}" fill="url(#scan)"/>',
        f'<rect class="sweep" x="2" y="0" width="{width-4}" height="60" fill="{ARTC}" opacity="0.035"/>',
        f'<rect class="frame" x="1" y="1" width="{width-2}" height="{height-2}" rx="14" fill="none" '
        f'stroke="url(#edge)" stroke-width="1.5"/>',
        "</svg>",
    ]


# ---------------------------------------------------------------- name banner
GLYPHS = {
    "A": [".###.", "#...#", "#...#", "#####", "#...#", "#...#", "#...#"],
    "L": ["#....", "#....", "#....", "#....", "#....", "#....", "#####"],
    "I": ["#####", "..#..", "..#..", "..#..", "..#..", "..#..", "#####"],
    "H": ["#...#", "#...#", "#...#", "#####", "#...#", "#...#", "#...#"],
    "S": [".####", "#....", "#....", ".###.", "....#", "....#", "####."],
    "N": ["#...#", "##..#", "#.#.#", "#..##", "#...#", "#...#", "#...#"],
    " ": ["...", "...", "...", "...", "...", "...", "..."],
}


def text_grid(word):
    rows = ["" for _ in range(7)]
    for i, ch in enumerate(word):
        g = GLYPHS[ch]
        for r in range(7):
            rows[r] += g[r] + ("." if i < len(word) - 1 else "")
    return rows


def build_name():
    rnd = random.Random(7)
    grid = text_grid("ALI HASSAN")
    cols, rows = len(grid[0]), 7
    px, gap = 12, 3
    step = px + gap
    height = 270
    gw, gh = cols * step - gap, rows * step - gap
    ox, oy = (W - gw) / 2, 70

    style = (
        ".off{fill:#161d29}"
        ".on{opacity:0;animation:fade .15s linear forwards}"
        ".word{animation:glow 3.5s ease-in-out 2.4s infinite}"
        "@keyframes glow{0%,100%{filter:drop-shadow(0 0 2px #1f6feb)}50%{filter:drop-shadow(0 0 9px #39c5cf)}}"
        ".gr{opacity:0;animation:gr 6s steps(1) 3s infinite}"
        ".gc{opacity:0;animation:gc 6s steps(1) 3s infinite}"
        "@keyframes gr{0%,100%{opacity:0}88%{opacity:.8;transform:translate(-5px,1px)}"
        "90%{opacity:.8;transform:translate(4px,-1px)}92%{opacity:0}}"
        "@keyframes gc{0%,100%{opacity:0}88%{opacity:.8;transform:translate(5px,-1px)}"
        "90%{opacity:.8;transform:translate(-4px,1px)}92%{opacity:0}}"
        ".t{opacity:0;animation:fade .01s linear forwards}"
        ".tag{opacity:0;animation:fade .4s ease forwards}"
    )
    out = window(W, height, f"~/{USER} — boot", style)
    out.append('<defs><linearGradient id="lg" x1="0" y1="0" x2="1" y2="0">'
               '<stop offset="0" stop-color="#39c5cf"/><stop offset="0.5" stop-color="#58a6ff"/>'
               '<stop offset="1" stop-color="#a371f7"/></linearGradient></defs>')

    # corner tags
    out.append(f'<text class="tag" style="animation-delay:.1s" x="28" y="60" font-size="11" fill="{DIM}">'
               f'SYS://{USER.upper()}</text>')
    out.append(f'<text class="tag" style="animation-delay:.2s" x="{W-28}" y="60" font-size="11" '
               f'text-anchor="end" fill="{DIM}">[ ONLINE ] ●</text>')

    on_cells = []
    off = []
    for r in range(rows):
        for c in range(cols):
            x, y = ox + c * step, oy + r * step
            off.append(f'<rect class="off" x="{x}" y="{y}" width="{px}" height="{px}" rx="2"/>')
            if grid[r][c] == "#":
                on_cells.append((x, y))
    out.extend(off)

    # lit pixels arrive in random order = "decrypt" effect
    order = list(range(len(on_cells)))
    rnd.shuffle(order)
    delay = {idx: 0.4 + k * (1.6 / len(order)) for k, idx in enumerate(order)}
    lit = [f'<rect class="on" style="animation-delay:{delay[i]:.2f}s" x="{x}" y="{y}" width="{px}" '
           f'height="{px}" rx="2"/>' for i, (x, y) in enumerate(on_cells)]
    plain = [f'<rect x="{x}" y="{y}" width="{px}" height="{px}" rx="2"/>' for x, y in on_cells]
    out.append('<g class="gr" fill="#ff2e88">' + "".join(plain) + "</g>")
    out.append('<g class="gc" fill="#00e5ff">' + "".join(plain) + "</g>")
    out.append('<g class="word" fill="url(#lg)">' + "".join(lit) + "</g>")

    # typed subtitle
    sub = "> Computer Engineering Student  //  FPGA · Hardware · ML"
    t0 = 2.2
    spans = "".join(
        f'<tspan class="t" style="animation-delay:{t0 + i*0.035:.3f}s">{escape(ch)}</tspan>'
        for i, ch in enumerate(sub))
    ty = oy + gh + 52
    out.append(f'<text x="{W/2}" y="{ty}" text-anchor="middle" font-size="17" fill="{VAL}" '
               f'xml:space="preserve">{spans}<tspan class="cur" fill="{ACC}"> █</tspan></text>')
    out += close(W, height)
    return "\n".join(out)


# ---------------------------------------------------------------- terminal
RW = 52  # chars in right column


def kv(key, val, width=RW):
    dots = width - len(key) - len(str(val)) - 5
    return [(DIM, ". "), (KEY, key), (FG, ":"), (DIM, " " + "." * max(dots, 1) + " "), (VAL, str(val))]


def kv2(k1, v1, k2, v2):
    return kv(k1, v1, 27) + [(DIM, " | ")] + kv(k2, v2, 22)[1:]


def head(title):
    return [(DIM, "- "), (ACC, title), (DIM, " " + "—" * (RW - len(title) - 3))]


def tspans(parts):
    return "".join(f'<tspan fill="{c}">{escape(t)}</tspan>' for c, t in parts)


def matrix_panel(x, y, w, h, rnd):
    out = [f'<clipPath id="mclip"><rect x="{x}" y="{y+26}" width="{w}" height="{h-26}"/></clipPath>',
           f'<g clip-path="url(#mclip)">']
    chars = "01ABCDEF<>/=#$%&*+アイウエオカキクケコ"
    fs, lh = 12, 14
    ncol = int(w // 11)
    for c in range(ncol):
        n = rnd.randint(8, 16)
        dur = rnd.uniform(3.5, 7.5)
        delay = -rnd.uniform(0, dur)
        cx = x + 6 + c * 11
        spans = []
        for k in range(n):
            op = 0.15 + 0.85 * (k / (n - 1))
            col = "#e6fffa" if k == n - 1 else "#3fb950"
            spans.append(f'<tspan x="{cx}" dy="{lh}" fill="{col}" fill-opacity="{op:.2f}">'
                         f'{escape(rnd.choice(chars))}</tspan>')
        out.append(f'<text font-size="{fs}" y="{y - n*lh}" style="animation:rain {dur:.2f}s linear '
                   f'{delay:.2f}s infinite">{"".join(spans)}</text>')
    out.append("</g>")
    return out


def ascii_name_panel(x, y, w, h, rnd):
    grid = text_grid("ALI")
    fs, cw, lh = 12, 7.22, 12
    cols = len(grid[0]) * 3
    tw = cols * cw
    x0 = x + (w - tw) / 2
    y0 = y + 26 + (h - 26 - 14 * lh) / 2 + lh
    dense = "@#%&$8BWM"
    noise = " .:-=+*#%@"
    out = []
    for r in range(14):
        line_l, line_n = "", ""
        for c in range(cols):
            on = grid[r // 2][c // 3] == "#"
            line_l += rnd.choice(dense) if on else " "
            line_n += rnd.choice(noise)
        yy = y0 + r * lh
        # scrambled noise that fades away, then the letters lock in
        out.append(f'<text class="nz" style="animation-delay:{2.6 + r*0.05:.2f}s" x="{x0}" y="{yy}" '
                   f'font-size="{fs}" fill="{DIM}" xml:space="preserve">{escape(line_n)}</text>')
        out.append(f'<text class="lk" style="animation-delay:{3.3 + r*0.07:.2f}s" x="{x0}" y="{yy}" '
                   f'font-size="{fs}" fill="url(#lg2)" xml:space="preserve">{escape(line_l)}</text>')
    return out


def build_terminal(s):
    rnd = random.Random(42)
    s = s or {k: "-" for k in ("repos", "stars", "followers", "contributed", "commits", "prs",
                                "issues", "year", "active")} | {"created": None}
    up = uptime(s["created"]) if s.get("created") else "-"

    lines = [
        [(ACC, "ali"), (FG, "@"), (ACC, USER)],
        [(DIM, "—" * RW)],
        kv("Role", "Computer Engineering Student"),
        kv("Uptime", up),
        kv("Focus", "FPGA | Hardware | ML"),
        [],
        kv("Languages.Programming", "Python, C, C++, Java"),
        kv("Languages.Declarative", "Haskell, Prolog"),
        kv("Languages.HDL", "VHDL, Verilog"),
        kv("Languages.Web", "JavaScript, HTML, CSS"),
        kv("Frameworks", "Flask, TensorFlow, PyTorch"),
        kv("Tools", "Git, Linux, Quartus, Colab"),
        [],
        head("Contact"),
        kv("GitHub", f"github.com/{USER}"),
        [],
        head("GitHub Stats"),
        kv("Repos", f"{s['repos']} {{Contributed: {s['contributed']}}}"),
        kv2("Stars", s["stars"], "Followers", s["followers"]),
        kv2("Commits", s["commits"], "PRs", s["prs"]),
        [],
        head("Last 12 Months"),
        kv2("Contributions", s["year"], "Active days", s["active"]),
    ]

    top, LH = 64, 20
    art_x = 26
    rx = 478
    upper = max(len(ART), len(lines) + 1) * LH
    py = top + upper + 4
    ph = 230
    height = py + ph + 26
    pw = (W - 26 * 2 - 18) / 2

    style = (
        ".a{opacity:0;animation:fade .3s linear forwards}"
        ".l{opacity:0;animation:slide .35s ease forwards}"
        ".p{opacity:0;animation:fade .5s ease forwards}"
        ".nz{opacity:0;animation:nz 1.2s linear forwards}"
        "@keyframes nz{0%{opacity:0}15%{opacity:1}60%{opacity:1}100%{opacity:0}}"
        ".lk{opacity:0;animation:lk .3s steps(2) forwards, flick 7s steps(1) 6s infinite}"
        "@keyframes lk{to{opacity:1}}"
        "@keyframes flick{0%,100%{opacity:1}93%{opacity:.35}94%{opacity:1}96%{opacity:.5}97%{opacity:1}}"
        "@keyframes rain{from{transform:translateY(0)}to{transform:translateY(" + str(ph + 260) + "px)}}"
    )
    out = window(W, height, f"ali@{USER}: ~/README.md", style)
    out.append('<defs><linearGradient id="lg2" x1="0" y1="0" x2="1" y2="1">'
               '<stop offset="0" stop-color="#39c5cf"/><stop offset="1" stop-color="#a371f7"/>'
               '</linearGradient></defs>')

    for i, l in enumerate(ART):
        out.append(f'<text class="a" style="animation-delay:{i*0.06:.2f}s" x="{art_x}" y="{top + i*LH}" '
                   f'fill="{ARTC}" xml:space="preserve">{escape(l)}</text>')
    for i, parts in enumerate(lines):
        if parts:
            out.append(f'<text class="l" style="animation-delay:{0.3 + i*0.09:.2f}s" x="{rx}" '
                       f'y="{top + i*LH}" xml:space="preserve">{tspans(parts)}</text>')
    cy = top + len(lines) * LH
    out.append(f'<text class="l" style="animation-delay:{0.3 + len(lines)*0.09:.2f}s" x="{rx}" y="{cy}">'
               f'<tspan fill="{ACC}">ali@{USER}:~$ </tspan><tspan class="cur" fill="{FG}">█</tspan></text>')

    # bottom panels
    for k, title in enumerate([f"{USER} @ ~/name", "~/matrix — live feed"]):
        x = 26 + k * (pw + 18)
        out.append(f'<g class="p" style="animation-delay:{2.3 + k*0.2:.1f}s">')
        out.append(f'<rect x="{x}" y="{py}" width="{pw}" height="{ph}" rx="8" fill="#0d131c" '
                   f'stroke="#30363d"/>')
        out.append(f'<path d="M{x} {py+8}a8 8 0 0 1 8-8h{pw-16}a8 8 0 0 1 8 8v18H{x}z" fill="{BAR}"/>')
        out.append(f'<text x="{x+12}" y="{py+18}" font-size="11" fill="#6e7681">{escape(title)}</text>')
        out.append(f'<text x="{x+pw-12}" y="{py+18}" font-size="11" fill="{ACC}" text-anchor="end">● REC</text>'
                   if k else f'<text x="{x+pw-12}" y="{py+18}" font-size="11" fill="#6e7681" '
                   f'text-anchor="end">decrypting…</text>')
        out.extend(ascii_name_panel(x, py, pw, ph, rnd) if k == 0 else matrix_panel(x, py, pw, ph, rnd))
        out.append("</g>")

    out += close(W, height)
    return "\n".join(out)


# ---------------------------------------------------------------- skills
def chip_icon(color, label):
    pins = "".join(f'<rect x="{3+i*4.5}" y="0" width="2" height="3" fill="{color}"/>'
                   f'<rect x="{3+i*4.5}" y="21" width="2" height="3" fill="{color}"/>'
                   f'<rect x="0" y="{3+i*4.5}" width="3" height="2" fill="{color}"/>'
                   f'<rect x="21" y="{3+i*4.5}" width="3" height="2" fill="{color}"/>' for i in range(4))
    return (f'{pins}<rect x="3" y="3" width="18" height="18" rx="2" fill="{color}"/>'
            f'<text x="12" y="15.5" text-anchor="middle" font-size="7" font-weight="bold" '
            f'fill="#0a0e14">{label}</text>')


def prolog_icon(color):
    return (f'<rect x="1" y="1" width="22" height="22" rx="5" fill="none" stroke="{color}" stroke-width="2"/>'
            f'<text x="12" y="16.5" text-anchor="middle" font-size="11" font-weight="bold" '
            f'fill="{color}">?-</text>')


