def build_skills():
    tw, th, gap = 88, 88, 10
    per_row = (W - 52 + gap) // (tw + gap)
    y = 64
    body = []
    k = 0
    for title, items in SKILLS:
        body.append(f'<text class="l" style="animation-delay:{k*0.04:.2f}s" x="{(W - (min(per_row, 9) * (tw + gap) - gap)) / 2}" y="{y}" font-size="14">'
                    f'<tspan fill="{ACC}">$ </tspan><tspan fill="{FG}">ls ~/skills/</tspan>'
                    f'<tspan fill="{KEY}">{escape(title.lower().replace(" / ", "-").replace(" & ", "-").replace(" ", "-"))}</tspan></text>')
        y += 16
        for i, (name, icon, color) in enumerate(items):
            r, c = divmod(i, per_row)
            n_in_row = min(per_row, len(items) - r * per_row)
            x = (W - (n_in_row * (tw + gap) - gap)) / 2 + c * (tw + gap)
            ty = y + r * (th + gap)
            if icon.startswith("@"):
                glyph = prolog_icon(color) if icon == "@prolog" else chip_icon(color, icon[1:])
            else:
                glyph = f'<path d="{ICONS[icon]}" fill="{color}"/>'
            d = 0.2 + k * 0.05
            body.append(
                f'<g class="tile" style="animation-delay:{d:.2f}s">'
                f'<rect x="{x}" y="{ty}" width="{tw}" height="{th}" rx="12" fill="#0f1620" stroke="{color}" '
                f'stroke-opacity=".35"/>'
                f'<rect class="glow" style="animation-delay:{(k*0.37)%4:.2f}s" x="{x}" y="{ty}" width="{tw}" '
                f'height="{th}" rx="12" fill="none" stroke="{color}" stroke-width="1.5"/>'
                f'<g transform="translate({x + tw/2 - 18},{ty + 14}) scale(1.5)">{glyph}</g>'
                f'<text x="{x + tw/2}" y="{ty + th - 13}" text-anchor="middle" font-size="11.5" '
                f'fill="{FG}">{escape(name)}</text></g>')
            k += 1
        rows = (len(items) + per_row - 1) // per_row
        y += rows * (th + gap) + 26
    height = y + 4
    style = (
        ".l{opacity:0;animation:slide .35s ease forwards}"
        ".tile{opacity:0;animation:pop .45s cubic-bezier(.2,1.4,.4,1) forwards;transform-box:fill-box;"
        "transform-origin:center}"
        "@keyframes pop{from{opacity:0;transform:scale(.6)}to{opacity:1;transform:none}}"
        ".glow{opacity:0;animation:gl 4s ease-in-out infinite}"
        "@keyframes gl{0%,100%{opacity:0}50%{opacity:.9}}"
    )
    out = window(W, height, "~/skills — tree", style)
    out += body
    out += close(W, height)
    return "\n".join(out)


# ---------------------------------------------------------------- stats dashboard
def streak_info(cal):
    if not cal:
        return 0, 0, "", ""
    counts = [c for _, c in cal]
    dates = [d for d, _ in cal]
    # current streak (today may still be 0 without breaking it)
    i = len(counts) - 1
    if counts[i] == 0:
        i -= 1
    cur, end_i = 0, i
    while i >= 0 and counts[i] > 0:
        cur += 1
        i -= 1
    best = run = 0
    best_end = 0
    for k, c in enumerate(counts):
        run = run + 1 if c > 0 else 0
        if run > best:
            best, best_end = run, k

    def fmt(a, b):
        f = lambda d: dt.date.fromisoformat(d).strftime("%b %-d")
        return f"{f(dates[a])} – {f(dates[b])}" if a != b else f(dates[a])
    cur_rng = fmt(end_i - cur + 1, end_i) if cur else "start today!"
    best_rng = fmt(best_end - best + 1, best_end) if best else "—"
    return cur, best, cur_rng, best_rng


