        "@keyframes ring{to{stroke-dashoffset:0}}"
        ".flame{transform-box:fill-box;transform-origin:center bottom;animation:flick 1.2s ease-in-out infinite}"
        "@keyframes flick{0%,100%{transform:scale(1)}50%{transform:scale(1.12,.92)}}"
        ".draw{stroke-dasharray:1000;stroke-dashoffset:1000;animation:draw 2.4s ease-out 1s forwards}"
        "@keyframes draw{to{stroke-dashoffset:0}}"
        ".area{opacity:0;animation:fade 1s ease 2.4s forwards}"
